    sec = data[1]
    n = int(data[2])

    n = (n - 1) % 4 + 1

    all_chars = "<^>v"
    start = all_chars.index(first[0])
    end = all_chars.index(sec[0])

    if start == end or (start - end) % 4 == 2:
        print("undefined")
    else:
        diff = (end - start) % 4
        if diff == 1:
            if n == 1:
                print("cw")
            elif n == 3:
                print("ccw")
        elif diff == 3:
            if n == 1:
                print("ccw")
            elif n == 3:
                print("cw")

if __name__ == "__main__":
